1123			}
1124			if assets[p.AssetID] == nil {
1125				return fmt.Errorf("数据矛盾：保养计划引用了不存在的资产 %s", p.AssetID)
1126			}
1127			if plans[p.AssetID] != nil {
1128				return fmt.Errorf("数据矛盾：资产 %s 有多个保养计划，最多允许一个", p.AssetID)
1129			}
1130			if _, err := parseDate(p.FirstDue); err != nil {
1131				return fmt.Errorf("数据矛盾：资产 %s 保养计划的首次到期日无效", p.AssetID)
1132			}
1133			if p.IntervalDays < 1 {
1134				return fmt.Errorf("数据矛盾：资产 %s 保养计划的间隔天数须为正整数", p.AssetID)
1135			}
1136			if _, err := parseDate(p.NextDue); err != nil {
1137				return fmt.Errorf("数据矛盾：资产 %s 保养计划的下一到期日无效", p.AssetID)
1138			}
1139			plans[p.AssetID] = p
1140		}
1141		// 保养履历链：每个计划恰有一条建立履历；建立与每次调整以各自的全库履历序号
1142		// 划分方案段（不按日期或数组位置），当前段方案为最近一次建立或调整记录的
1143		// 内容、首次到期日与间隔。完成履历按序号接续（周期到期日须等于当时下一
1144		// 到期日，完成日不早于它，按当时所在段的首次日加整数倍间隔推进），撤销履历
1145		// 须引用当时所在段内未撤销且最新有效的完成，并把下一到期日恢复为该完成的
1146		// 周期到期日；调整履历记录的原方案与原下一到期日须与当时状态一致，新首次
1147		// 到期日须严格晚于当时所有未撤销完成的实际完成日，调整后下一到期日即新
1148		// 首次到期日，旧段完成不能再撤销。由履历推出的当前方案与下一到期日须与
1149		// 计划保存的一致。没有计划的资产不得有保养履历。停用状态随全库履历序号
1150		// 推进：停用期间不得登记保养完成；停用不暂停、不重算周期，因此建立、完成、
1151		// 撤销与调整的接续规则本身不受影响。以上判定与状态推进全部由保养规则核心
1152		// （maintcore.go）完成，与日常操作共用同一套规则；核心只读履历，不修改
1153		// 任何业务记录，也不补字段或修复数据。
1154		core := newMaintCore()
1155		for _, e := range sorted {
1156			if isPlanEvent(e.Kind) && plans[e.AssetID] == nil {
1157				return fmt.Errorf("履历矛盾：资产 %s 没有保养计划，却存在保养履历（序号 %d）", e.AssetID, e.Seq)
1158			}
1159			if err := core.apply(e); err != nil {
1160				return maintValidateError(err)
1161			}
1162		}
1163		for _, p := range d.Plans {
1164			content, firstDue, interval, nextDue, created := core.derived(p.AssetID)
1165			if !created {
1166				return fmt.Errorf("履历矛盾：资产 %s 的保养计划应有恰一条建立履历，实际没有", p.AssetID)
1167			}
1168			if content != p.Content || firstDue != p.FirstDue || interval != p.IntervalDays {
1169				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的当前方案（内容 %q、首次到期日 %s、每 %d 天）与保存的方案（内容 %q、首次到期日 %s、每 %d 天）不符",
1170					p.AssetID, content, firstDue, interval,
1171					p.Content, p.FirstDue, p.IntervalDays)
1172			}
1173			if nextDue != p.NextDue {
1174				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的下一到期日为 %s，与保存的 %s 不符",
1175					p.AssetID, nextDue, p.NextDue)
1176			}
1177		}
1178		return nil
1179	}
