1427	// closeTicket 关闭未关闭工单并把资产恢复为可用。
1428	// 失败路径不修改任何业务数据。
1429	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
1430		t := s.findTicket(ticketID)
1431		if t == nil {
1432			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1433		}
1434		if t.Status == ticketCancelled {
1435			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
1436		}
1437		if t.Status != ticketOpen {
1438			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
1439		}
1440		asset := s.findAsset(t.AssetID)
1441		if asset == nil {
1442			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1443		}
1444		eventSeq, err := s.nextEventSeq()
1445		if err != nil {
1446			return nil, nil, err
1447		}
1448		t.Status = ticketClosed
1449		t.Result = result
1450		t.ClosedAt = s.now().Format(time.RFC3339)
1451		asset.Status = statusAvailable
1452		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
1453		return t, asset, nil
1454	}
