1456	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
1457	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
1458	// 失败路径不修改任何业务数据。
1459	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
1460		t := s.findTicket(ticketID)
1461		if t == nil {
1462			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1463		}
1464		if t.Status == ticketCancelled {
1465			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
1466		}
1467		if t.Status == ticketClosed {
1468			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
1469		}
1470		asset := s.findAsset(t.AssetID)
1471		if asset == nil {
1472			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1473		}
1474		eventSeq, err := s.nextEventSeq()
1475		if err != nil {
1476			return nil, nil, err
1477		}
1478		t.Status = ticketCancelled
1479		t.CancelReason = reason
1480		t.CancelledAt = s.now().Format(time.RFC3339)
1481		asset.Status = statusAvailable
1482		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
1483		return t, asset, nil
1484	}
