99	// attach 为工单登记本地资料附件索引：未关闭、已关闭或已取消工单均可补充。
100	// 生成同目录唯一且不复用的附件编号，追加一条登记履历。path 须为调用方已
101	// 解析得到的绝对路径，且登记时须为存在且可读的普通文件。每次登记独立：
102	// 同路径不合并，不使用报修请求标识去重。失败路径不修改任何业务数据，
103	// 也不消耗附件编号。
104	func (s *store) attach(ticketID, path, note string) (*Attachment, error) {
105		t := s.findTicket(ticketID)
106		if t == nil {
107			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
108		}
109		if note == "" {
110			return nil, fmt.Errorf("%w: 附件说明不能为空", errConflict)
111		}
112		if err := checkAttachFile(path); err != nil {
113			return nil, err
114		}
115		// 先确认附件编号与履历计数器都能推进，再修改任何业务数据：
116		// 编号耗尽时拒绝登记，不消耗编号，也不产生履历。
117		seq := s.data.NextAttachSeq
118		if seq < 1 || seq == math.MaxInt {
119			return nil, fmt.Errorf("%w: 附件编号计数器已耗尽，无法分配新附件编号", errConflict)
120		}
121		eventSeq, err := s.nextEventSeq()
122		if err != nil {
123			return nil, err
124		}
125		a := &Attachment{
126			ID:       fmt.Sprintf("A%04d", seq),
127			TicketID: t.ID,
128			AssetID:  t.AssetID,
129			Path:     path,
130			Note:     note,
131		}
132		s.data.NextAttachSeq = seq + 1
133		s.data.Attachments = append(s.data.Attachments, a)
134		s.appendAttachEvent(eventSeq, a, eventAttach, note)
135		return a, nil
136	}
137	
138	// revokeAttachment 按附件编号撤销附件索引：保留记录、路径、说明与撤销理由，
139	// 追加一条撤销履历。已撤销编号不能恢复（可重新登记为新索引）；工单终结不
140	// 自动撤销附件，撤销也不受工单状态限制。失败路径不修改任何业务数据。
141	func (s *store) revokeAttachment(id, reason string) (*Attachment, error) {
142		a := s.findAttachment(id)
143		if a == nil {
144			return nil, fmt.Errorf("%w: 未知附件编号 %q", errNotFound, id)
145		}
146		if a.Revoked {
147			return nil, fmt.Errorf("%w: 附件 %s 已撤销，不能重复撤销", errConflict, id)
148		}
149		if reason == "" {
150			return nil, fmt.Errorf("%w: 撤销理由不能为空", errConflict)
151		}
152		eventSeq, err := s.nextEventSeq()
153		if err != nil {
154			return nil, err
155		}
156		a.Revoked = true
157		a.RevokeReason = reason
158		s.appendAttachEvent(eventSeq, a, eventAttachRevoke, reason)
159		return a, nil
160	}
