14	// 资产批量导入：把源数据目录中所选资产连同其全部工单、报修请求绑定、
15	// 报修/派工/关闭/取消履历、停用/恢复使用履历（含当前停用或可用状态）、
16	// 位置起点（最早一条位置变更履历的原位置；没有位置履历则为资产保存位置）、
17	// 当前位置与全部位置变更履历、备件领用记录、附件索引（含登记/撤销履历）
18	// 与保养计划（含保养建立/完成/撤销/调整履历）复制到目标数据目录。
19	//
20	// 关键规则：
21	//   - 导入是复制：源台账始终只读，不删除、不修改任何源记录；同一台账不能导入自身。
22	//   - 工单编号按源工单序号升序，从目标的下一工单序号重新分配，并同步替换履历与
23	//     请求绑定中的工单引用；目标原有记录不改编号、不改变业务含义。
24	//   - 备件领用编号按源领用履历的全库序号整体排序（编号大小不代表领用先后），
25	//     从目标的下一领用序号重新分配并输出映射；领用记录的工单引用与退回履历中的
26	//     领用引用同步替换，数量、累计退回与净量保持。导入的未关闭工单可继续退回。
27	//   - 附件编号按源登记履历的全库序号整体排序，从目标的下一附件序号重新分配并
28	//     输出映射；附件记录的工单引用与登记、撤销履历中的附件引用同步替换，路径、
29	//     撤销状态、说明与理由保持。只复制索引，不复制资料文件；文件当前不可用不使
30	//     导入失败。
31	//   - 履历按源履历序号排列，在目标已有最大履历序号之后依次分配新序号，保留原操作
32	//     顺序（不按时间重排）；履历时间保留原瞬间与小数秒精度。导入本身不追加报修
33	//     或其他业务事件。
34	//   - 保养计划随资产原样复制（内容、首次到期日、间隔与下一到期日不变），保养履历
35	//     （含撤销与调整履历）随资产履历一并复制，完成与撤销链自然接续，方案段边界、
36	//     顺序与时间精度保持，撤销履历中的目标
37	//     完成序号随履历重编号同步替换，并输出完成履历序号的原、新映射；目标已有计划
38	//     不受影响。导入后可用新完成序号继续撤销，也可继续调整方案。
39	//   - 停用、恢复使用为资产级履历，随资产履历一并复制并重编号，资产当前的停用或
40	//     可用状态原样保留；导入后可继续恢复使用或停用。
41	//   - 位置起点、当前位置与全部位置变更履历随资产一并复制并沿用履历重编号，保留
42	//     原位置、新位置、理由的先后关系与时间精度；导入本身不新增搬移事件。工单
43	//     复制时保留其报修地点（即源台账报修履历序号当时的资产位置），导入后的
44	//     工单报修地点保持不变，资产可在目标库继续变更位置。
45	//   - 资产编号在目标已存在，或所选工单的任一请求标识已在目标绑定时，整批拒绝：
46	//     不覆盖、不合并、不改请求标识。
47	//   - 操作前检查源、目标整库一致性，提交前由 save 再检查合并后的数据；整批变化
48	//     一次原子写入目标。任何失败都不改动两边原文件、不留下部分导入、不消耗目标编号。
49	
50	// stringListFlag 收集可重复的 --asset-id 参数。
51	type stringListFlag []string
52	
53	func (f *stringListFlag) String() string { return strings.Join(*f, ",") }
54	
55	func (f *stringListFlag) Set(v string) error {
56		*f = append(*f, v)
57		return nil
58	}
59	
60	// ticketRemap 记录一张工单的原编号与新编号。
61	type ticketRemap struct {
62		OldID string
63		NewID string
64	}
65	
66	// partRemap 记录一笔备件领用的原领用编号与新领用编号。
67	type partRemap struct {
68		OldID string
69		NewID string
70	}
71	
72	// attachRemap 记录一条附件索引的原附件编号与新附件编号。
73	type attachRemap struct {
74		OldID string
75		NewID string
76	}
77	
78	// completionRemap 记录一条保养完成履历的原全库序号与新全库序号。
79	type completionRemap struct {
80		OldSeq int
81		NewSeq int
82	}
83	
84	// importOutcome 为一次成功导入的结果摘要，用于输出。
85	type importOutcome struct {
86		assetIDs    []string
87		tickets     []ticketRemap
88		parts       []partRemap
89		attachments []attachRemap
90		completions []completionRemap
91		plans       int
92	}
93	
94	func cmdImport(args []string, w io.Writer) error {
95		var opts cmdOptions
96		var sourceDir string
97		var assetIDs stringListFlag
98		fs := newFlagSet("import", &opts)
99		fs.StringVar(&sourceDir, "source-dir", "", "源数据目录（必填，只读，不会被修改）")
100		fs.Var(&assetIDs, "asset-id", "要导入的资产编号（必填，可重复；重复编号按一项处理）")
101		if err := parseFlags(fs, args); err != nil {
102			return err
103		}
104		if err := requireFlag(fs, sourceDir, "source-dir"); err != nil {
105			return err
106		}
107		if len(assetIDs) == 0 {
108			return &usageError{msg: "命令 import 缺少必填参数 --asset-id（至少一项资产编号）"}
109		}
110		for _, id := range assetIDs {
111			if id == "" {
112				return &usageError{msg: "命令 import 的 --asset-id 不能为空"}
113			}
114		}
115	
116		outcome, err := importAssets(opts.dataDir, sourceDir, []string(assetIDs))
117		if err != nil {
118			return err
119		}
120		fmt.Fprintf(w, "已导入 %d 项资产（%s）。\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
121		if outcome.plans > 0 {
122			fmt.Fprintf(w, "同时导入 %d 项保养计划及其保养履历。\n", outcome.plans)
123		}
124		if len(outcome.tickets) == 0 {
125			fmt.Fprintln(w, "所选资产没有工单，未分配新工单编号。")
126		} else {
127			fmt.Fprintln(w, "工单编号映射（原编号 -> 新编号）:")
128			for _, m := range outcome.tickets {
129				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
130			}
131		}
132		if len(outcome.parts) > 0 {
133			fmt.Fprintln(w, "领用编号映射（原编号 -> 新编号）:")
134			for _, m := range outcome.parts {
135				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
136			}
137		}
138		if len(outcome.attachments) > 0 {
139			fmt.Fprintln(w, "附件编号映射（原编号 -> 新编号）:")
140			for _, m := range outcome.attachments {
141				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
142			}
143		}
144		if len(outcome.completions) > 0 {
145			fmt.Fprintln(w, "完成履历序号映射（原序号 -> 新序号）:")
146			for _, m := range outcome.completions {
147				fmt.Fprintf(w, "%d -> %d\n", m.OldSeq, m.NewSeq)
148			}
149		}
150		return nil
151	}
152	
153	// importAssets 把 sourceDir 中编号为 assetIDs 的资产导入 targetDir。
154	// 源目录只读；目标目录无台账时在成功导入时创建。任何一步失败都整批失败，
155	// 两边原文件字节保持不变。
156	func importAssets(targetDir, sourceDir string, assetIDs []string) (*importOutcome, error) {
157		srcAbs, err := filepath.Abs(sourceDir)
158		if err != nil {
159			return nil, fmt.Errorf("无法解析源数据目录: %w", err)
160		}
161		dstAbs, err := filepath.Abs(targetDir)
162		if err != nil {
163			return nil, fmt.Errorf("无法解析目标数据目录: %w", err)
164		}
165		if srcAbs == dstAbs {
166			return nil, errors.New("源数据目录与目标数据目录相同：同一台账不能导入自身")
167		}
168		// 路径不同也可能指向同一台账文件（符号链接等），按文件再判一次。
169		srcPath := filepath.Join(srcAbs, dataFileName)
170		dstPath := filepath.Join(dstAbs, dataFileName)
171		if fi1, err1 := os.Stat(srcPath); err1 == nil {
172			if fi2, err2 := os.Stat(dstPath); err2 == nil && os.SameFile(fi1, fi2) {
173				return nil, errors.New("源与目标指向同一台账文件：同一台账不能导入自身")
174			}
175		}
176	
177		// 源台账必须已存在并通过整库一致性检查；源始终只读，绝不写入。
178		src, err := openSourceStore(srcAbs)
179		if err != nil {
180			return nil, err
181		}
182		// 目标：无台账时视为空库（成功导入时创建）；已有台账同样先做整库一致性检查。
183		dst, err := openStore(dstAbs)
184		if err != nil {
185			return nil, err
186		}
187		outcome, err := dst.mergeImport(src, assetIDs)
188		if err != nil {
189			return nil, err
190		}
191		// save 先校验合并后的整库一致性，再一次性原子写入；失败时目标原文件不变。
192		if err := dst.save(); err != nil {
193			return nil, err
194		}
195		return outcome, nil
196	}
197	
198	// mergeImport 在内存中把源台账的所选资产合并进目标数据：先做全部冲突与容量
199	// 检查，再一次性应用，任何失败都不会留下部分变更。调用方负责随后的原子保存。
200	func (s *store) mergeImport(src *store, assetIDs []string) (*importOutcome, error) {
201		// 重复编号按一项处理，保持首次出现的顺序。
202		selected := map[string]bool{}
203		ids := make([]string, 0, len(assetIDs))
204		for _, id := range assetIDs {
205			if !selected[id] {
206				selected[id] = true
207				ids = append(ids, id)
208			}
209		}
210		// 所选资产必须存在于源，且编号在目标中不存在。
211		assets := make([]*Asset, 0, len(ids))
212		for _, id := range ids {
213			a := src.findAsset(id)
214			if a == nil {
215				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
216			}
217			if s.findAsset(id) != nil {
218				return nil, fmt.Errorf("%w: 资产编号 %q 在目标台账中已存在，整批拒绝导入", errConflict, id)
219			}
220			assets = append(assets, a)
221		}
222		// 所选资产的全部工单，按源工单序号升序重新分配编号。
223		tickets := make([]*Ticket, 0)
224		for _, t := range src.data.Tickets {
225			if selected[t.AssetID] {
226				tickets = append(tickets, t)
227			}
228		}
229		sort.SliceStable(tickets, func(i, j int) bool {
230			ni, _ := parseTicketSeq(tickets[i].ID)
231			nj, _ := parseTicketSeq(tickets[j].ID)
232			return ni < nj
233		})
234		// 工单编号容量：与 report 同一约束，可分配的最大序号为 math.MaxInt-1。
235		if len(tickets) > math.MaxInt-s.data.NextTicketSeq {
236			return nil, fmt.Errorf(
237				"%w: 目标工单编号容量不足：下一序号 %d 无法容纳 %d 张导入工单，整批拒绝导入",
238				errConflict, s.data.NextTicketSeq, len(tickets))
239		}
240		// 所选工单的任一请求标识已在目标绑定时整批拒绝，不改请求标识。
241		srcReqByTicket := map[string]*requestBinding{}
242		for i := range src.data.Requests {
243			r := &src.data.Requests[i]
244			srcReqByTicket[r.TicketID] = r
245		}
246		for _, t := range tickets {
247			r := srcReqByTicket[t.ID]
248			if r == nil {
249				return nil, fmt.Errorf("数据内部错误：源工单 %s 缺少报修请求绑定", t.ID)
250			}
251			if s.findRequest(r.RequestID) != nil {
252				return nil, fmt.Errorf(
253					"%w: 所选工单的请求标识 %q 已在目标台账绑定，整批拒绝导入", errConflict, r.RequestID)
254			}
255		}
256		// 所选资产的全部履历，按源履历序号升序，在目标最大序号之后依次分配。
257		events := make([]Event, 0)
258		for _, e := range src.data.Events {
259			if selected[e.AssetID] {
260				events = append(events, e)
261			}
262		}
263		sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
264		maxSeq := 0
265		for _, e := range s.data.Events {
266			if e.Seq > maxSeq {
267				maxSeq = e.Seq
268			}
269		}
270		// 履历序号容量：与 nextEventSeq 同一约束，可分配的最大序号为 math.MaxInt。
271		if len(events) > math.MaxInt-maxSeq {
272			return nil, fmt.Errorf(
273				"%w: 目标履历序号容量不足：当前最大序号 %d 无法容纳 %d 条导入履历，整批拒绝导入",
274				errConflict, maxSeq, len(events))
275		}
276		// 所选工单的全部备件领用记录，按源领用履历的全库序号整体排序（领用编号
277		// 只定位记录，编号大小不代表领用先后），再按此顺序重新分配领用编号。
278		srcTicketIDs := map[string]bool{}
279		for _, t := range tickets {
280			srcTicketIDs[t.ID] = true
281		}
282		srcWithdrawSeq := map[string]int{}
283		for _, e := range src.data.Events {
284			if e.Kind == eventPartWithdraw {
285				srcWithdrawSeq[e.WithdrawalID] = e.Seq
286			}
287		}
288		parts := make([]*PartWithdrawal, 0)
289		for _, p := range src.data.Parts {
290			if srcTicketIDs[p.TicketID] {
291				parts = append(parts, p)
292			}
293		}
294		sort.SliceStable(parts, func(i, j int) bool {
295			return srcWithdrawSeq[parts[i].ID] < srcWithdrawSeq[parts[j].ID]
296		})
297		// 领用编号容量：与 withdrawPart 同一约束，可分配的最大序号为 math.MaxInt-1。
298		if len(parts) > math.MaxInt-s.data.NextPartSeq {
299			return nil, fmt.Errorf(
300				"%w: 目标领用编号容量不足：下一序号 %d 无法容纳 %d 笔导入领用，整批拒绝导入",
301				errConflict, s.data.NextPartSeq, len(parts))
302		}
303		// 所选工单的全部附件索引（有效与已撤销都复制），按源登记履历的全库序号
304		// 整体排序（附件编号只定位记录，编号大小不代表登记先后），再按此顺序重新
305		// 分配附件编号。只复制索引记录与履历，不复制资料文件；文件当前不可用不使
306		// 导入失败。
307		srcAttachRegSeq := map[string]int{}
308		for _, e := range src.data.Events {
309			if e.Kind == eventAttach {
310				srcAttachRegSeq[e.AttachmentID] = e.Seq
311			}
312		}
313		attachments := make([]*Attachment, 0)
314		for _, a := range src.data.Attachments {
315			if srcTicketIDs[a.TicketID] {
316				attachments = append(attachments, a)
317			}
318		}
319		sort.SliceStable(attachments, func(i, j int) bool {
320			return srcAttachRegSeq[attachments[i].ID] < srcAttachRegSeq[attachments[j].ID]
321		})
322		// 附件编号容量：与 attach 同一约束，可分配的最大序号为 math.MaxInt-1。
323		if len(attachments) > math.MaxInt-s.data.NextAttachSeq {
324			return nil, fmt.Errorf(
325				"%w: 目标附件编号容量不足：下一序号 %d 无法容纳 %d 条导入附件索引，整批拒绝导入",
326				errConflict, s.data.NextAttachSeq, len(attachments))
327		}
328	
329		// 检查全部通过，一次性应用合并。资产编号、名称、位置、状态与工单的描述、
330		// 终态内容、负责人等业务信息原样保留；履历时间保留原瞬间与小数秒精度。
331		for _, a := range assets {
332			na := *a
333			s.data.Assets = append(s.data.Assets, &na)
334		}
335		// 所选资产的保养计划原样复制（内容、首次到期日、间隔与下一到期日不变）；
336		// 保养履历已随上方资产履历筛选一并复制，完成链自然接续。目标已有计划不变。
337		planCount := 0
338		for _, p := range src.data.Plans {
339			if selected[p.AssetID] {
340				np := *p
341				s.data.Plans = append(s.data.Plans, &np)
342				planCount++
343			}
344		}
345		outcome := &importOutcome{assetIDs: ids, plans: planCount}
346		remap := map[string]string{}
347		next := s.data.NextTicketSeq
348		for _, t := range tickets {
349			nt := *t
350			nt.ID = fmt.Sprintf("T%04d", next)
351			remap[t.ID] = nt.ID
352			s.data.Tickets = append(s.data.Tickets, &nt)
353			r := srcReqByTicket[t.ID]
354			s.data.Requests = append(s.data.Requests, requestBinding{
355				RequestID:   r.RequestID,
356				AssetID:     r.AssetID,
357				Description: r.Description,
358				TicketID:    nt.ID,
359			})
360			outcome.tickets = append(outcome.tickets, ticketRemap{OldID: t.ID, NewID: nt.ID})
361			next++
362		}
363		s.data.NextTicketSeq = next
364		// 备件领用记录按源领用顺序重新分配领用编号，工单引用同步替换；
365		// 数量、累计退回与说明等业务信息原样保留。
366		partIDs := map[string]string{}
367		nextPart := s.data.NextPartSeq
368		for _, p := range parts {
369			np := *p
370			np.ID = fmt.Sprintf("P%04d", nextPart)
371			np.TicketID = remap[p.TicketID]
372			partIDs[p.ID] = np.ID
373			s.data.Parts = append(s.data.Parts, &np)
374			outcome.parts = append(outcome.parts, partRemap{OldID: p.ID, NewID: np.ID})
375			nextPart++
376		}
377		s.data.NextPartSeq = nextPart
378		// 附件索引按源登记顺序重新分配附件编号，工单引用同步替换；
379		// 路径、撤销状态、说明与撤销理由等业务信息原样保留。
380		attachIDs := map[string]string{}
381		nextAttach := s.data.NextAttachSeq
382		for _, a := range attachments {
383			na := *a
384			na.ID = fmt.Sprintf("A%04d", nextAttach)
385			na.TicketID = remap[a.TicketID]
386			attachIDs[a.ID] = na.ID
387			s.data.Attachments = append(s.data.Attachments, &na)
388			outcome.attachments = append(outcome.attachments, attachRemap{OldID: a.ID, NewID: na.ID})
389			nextAttach++
390		}
391		s.data.NextAttachSeq = nextAttach
392		seq := maxSeq
393		seqRemap := map[int]int{}
394		for _, e := range events {
395			seq++
396			ne := e
397			ne.Seq = seq
398			ne.TicketID = remap[e.TicketID]
399			ne.WithdrawalID = partIDs[e.WithdrawalID]
400			ne.AttachmentID = attachIDs[e.AttachmentID]
401			if e.Kind == eventPlanRevoke {
402				// 撤销履历的目标完成序号随履历重编号同步替换：目标在源序号顺序中
403				// 先于撤销出现（源台账已通过一致性检查），此处必然已有映射。
404				ne.TargetSeq = seqRemap[e.TargetSeq]
405			}
406			seqRemap[e.Seq] = seq
407			if e.Kind == eventPlanDone {
408				outcome.completions = append(outcome.completions, completionRemap{OldSeq: e.Seq, NewSeq: seq})
409			}
410			s.data.Events = append(s.data.Events, ne)
411		}
412		return outcome, nil
413	}
414

