package main

import (
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// 资产批量导入：把源数据目录中所选资产连同其全部工单、报修请求绑定、
// 报修/派工/关闭/取消履历、停用/恢复使用履历（含当前停用或可用状态）、
// 位置起点（最早一条位置变更履历的原位置；没有位置履历则为资产保存位置）、
// 当前位置与全部位置变更履历、备件领用记录、附件索引（含登记/撤销履历）
// 与保养计划（含保养建立/完成/撤销/调整履历）复制到目标数据目录。
//
// 关键规则：
//   - 导入是复制：源台账始终只读，不删除、不修改任何源记录；同一台账不能导入自身。
//   - 工单编号按源工单序号升序，从目标的下一工单序号重新分配，并同步替换履历与
//     请求绑定中的工单引用；目标原有记录不改编号、不改变业务含义。
//   - 备件领用编号按源领用履历的全库序号整体排序（编号大小不代表领用先后），
//     从目标的下一领用序号重新分配并输出映射；领用记录的工单引用与退回履历中的
//     领用引用同步替换，数量、累计退回与净量保持。导入的未关闭工单可继续退回。
//   - 附件编号按源登记履历的全库序号整体排序，从目标的下一附件序号重新分配并
//     输出映射；附件记录的工单引用与登记、撤销履历中的附件引用同步替换，路径、
//     撤销状态、说明与理由保持。只复制索引，不复制资料文件；文件当前不可用不使
//     导入失败。
//   - 履历按源履历序号排列，在目标已有最大履历序号之后依次分配新序号，保留原操作
//     顺序（不按时间重排）；履历时间保留原瞬间与小数秒精度。导入本身不追加报修
//     或其他业务事件。
//   - 保养计划随资产原样复制（内容、首次到期日、间隔与下一到期日不变），保养履历
//     （含撤销与调整履历）随资产履历一并复制，完成与撤销链自然接续，方案段边界、
//     顺序与时间精度保持，撤销履历中的目标
//     完成序号随履历重编号同步替换，并输出完成履历序号的原、新映射；目标已有计划
//     不受影响。导入后可用新完成序号继续撤销，也可继续调整方案。
//   - 停用、恢复使用为资产级履历，随资产履历一并复制并重编号，资产当前的停用或
//     可用状态原样保留；导入后可继续恢复使用或停用。
//   - 位置起点、当前位置与全部位置变更履历随资产一并复制并沿用履历重编号，保留
//     原位置、新位置、理由的先后关系与时间精度；导入本身不新增搬移事件。工单
//     复制时保留其报修地点（即源台账报修履历序号当时的资产位置），导入后的
//     工单报修地点保持不变，资产可在目标库继续变更位置。
//   - 资产编号在目标已存在，或所选工单的任一请求标识已在目标绑定时，整批拒绝：
//     不覆盖、不合并、不改请求标识。
//   - 操作前检查源、目标整库一致性，提交前由 save 再检查合并后的数据；整批变化
//     一次原子写入目标。任何失败都不改动两边原文件、不留下部分导入、不消耗目标编号。

// stringListFlag 收集可重复的 --asset-id 参数。
type stringListFlag []string

func (f *stringListFlag) String() string { return strings.Join(*f, ",") }

func (f *stringListFlag) Set(v string) error {
	*f = append(*f, v)
	return nil
}

// ticketRemap 记录一张工单的原编号与新编号。
type ticketRemap struct {
	OldID string
	NewID string
}

// partRemap 记录一笔备件领用的原领用编号与新领用编号。
type partRemap struct {
	OldID string
	NewID string
}

// attachRemap 记录一条附件索引的原附件编号与新附件编号。
type attachRemap struct {
	OldID string
	NewID string
}

// completionRemap 记录一条保养完成履历的原全库序号与新全库序号。
type completionRemap struct {
	OldSeq int
	NewSeq int
}

// importOutcome 为一次成功导入的结果摘要，用于输出。
type importOutcome struct {
	assetIDs    []string
	tickets     []ticketRemap
	parts       []partRemap
	attachments []attachRemap
	completions []completionRemap
	plans       int
}

func cmdImport(args []string, w io.Writer) error {
	var opts cmdOptions
	var sourceDir string
	var assetIDs stringListFlag
	fs := newFlagSet("import", &opts)
	fs.StringVar(&sourceDir, "source-dir", "", "源数据目录（必填，只读，不会被修改）")
	fs.Var(&assetIDs, "asset-id", "要导入的资产编号（必填，可重复；重复编号按一项处理）")
	if err := parseFlags(fs, args); err != nil {
		return err
	}
	if err := requireFlag(fs, sourceDir, "source-dir"); err != nil {
		return err
	}
	if len(assetIDs) == 0 {
		return &usageError{msg: "命令 import 缺少必填参数 --asset-id（至少一项资产编号）"}
	}
	for _, id := range assetIDs {
		if id == "" {
			return &usageError{msg: "命令 import 的 --asset-id 不能为空"}
		}
	}

	outcome, err := importAssets(opts.dataDir, sourceDir, []string(assetIDs))
	if err != nil {
		return err
	}
	fmt.Fprintf(w, "已导入 %d 项资产（%s）。\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
	if outcome.plans > 0 {
		fmt.Fprintf(w, "同时导入 %d 项保养计划及其保养履历。\n", outcome.plans)
	}
	if len(outcome.tickets) == 0 {
		fmt.Fprintln(w, "所选资产没有工单，未分配新工单编号。")
	} else {
		fmt.Fprintln(w, "工单编号映射（原编号 -> 新编号）:")
		for _, m := range outcome.tickets {
			fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
		}
	}
	if len(outcome.parts) > 0 {
		fmt.Fprintln(w, "领用编号映射（原编号 -> 新编号）:")
		for _, m := range outcome.parts {
			fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
		}
	}
	if len(outcome.attachments) > 0 {
		fmt.Fprintln(w, "附件编号映射（原编号 -> 新编号）:")
		for _, m := range outcome.attachments {
			fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
		}
	}
	if len(outcome.completions) > 0 {
		fmt.Fprintln(w, "完成履历序号映射（原序号 -> 新序号）:")
		for _, m := range outcome.completions {
			fmt.Fprintf(w, "%d -> %d\n", m.OldSeq, m.NewSeq)
		}
	}
	return nil
}

// importAssets 把 sourceDir 中编号为 assetIDs 的资产导入 targetDir。
// 源目录只读；目标目录无台账时在成功导入时创建。任何一步失败都整批失败，
// 两边原文件字节保持不变。
func importAssets(targetDir, sourceDir string, assetIDs []string) (*importOutcome, error) {
	srcAbs, err := filepath.Abs(sourceDir)
	if err != nil {
		return nil, fmt.Errorf("无法解析源数据目录: %w", err)
	}
	dstAbs, err := filepath.Abs(targetDir)
	if err != nil {
		return nil, fmt.Errorf("无法解析目标数据目录: %w", err)
	}
	if srcAbs == dstAbs {
		return nil, errors.New("源数据目录与目标数据目录相同：同一台账不能导入自身")
	}
	// 路径不同也可能指向同一台账文件（符号链接等），按文件再判一次。
	srcPath := filepath.Join(srcAbs, dataFileName)
	dstPath := filepath.Join(dstAbs, dataFileName)
	if fi1, err1 := os.Stat(srcPath); err1 == nil {
		if fi2, err2 := os.Stat(dstPath); err2 == nil && os.SameFile(fi1, fi2) {
			return nil, errors.New("源与目标指向同一台账文件：同一台账不能导入自身")
		}
	}

	// 源台账必须已存在并通过整库一致性检查；源始终只读，绝不写入。
	src, err := openSourceStore(srcAbs)
	if err != nil {
		return nil, err
	}
	// 目标：无台账时视为空库（成功导入时创建）；已有台账同样先做整库一致性检查。
	dst, err := openStore(dstAbs)
	if err != nil {
		return nil, err
	}
	outcome, err := dst.mergeImport(src, assetIDs)
	if err != nil {
		return nil, err
	}
	// save 先校验合并后的整库一致性，再一次性原子写入；失败时目标原文件不变。
	if err := dst.save(); err != nil {
		return nil, err
	}
	return outcome, nil
}

// mergeImport 在内存中把源台账的所选资产合并进目标数据：先做全部冲突与容量
// 检查，再一次性应用，任何失败都不会留下部分变更。调用方负责随后的原子保存。
func (s *store) mergeImport(src *store, assetIDs []string) (*importOutcome, error) {
	// 重复编号按一项处理，保持首次出现的顺序。
	selected := map[string]bool{}
	ids := make([]string, 0, len(assetIDs))
	for _, id := range assetIDs {
		if !selected[id] {
			selected[id] = true
			ids = append(ids, id)
		}
	}
	// 所选资产必须存在于源，且编号在目标中不存在。
	assets := make([]*Asset, 0, len(ids))
	for _, id := range ids {
		a := src.findAsset(id)
		if a == nil {
			return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
		}
		if s.findAsset(id) != nil {
			return nil, fmt.Errorf("%w: 资产编号 %q 在目标台账中已存在，整批拒绝导入", errConflict, id)
		}
		assets = append(assets, a)
	}
	// 所选资产的全部工单，按源工单序号升序重新分配编号。
	tickets := make([]*Ticket, 0)
	for _, t := range src.data.Tickets {
		if selected[t.AssetID] {
			tickets = append(tickets, t)
		}
	}
	sort.SliceStable(tickets, func(i, j int) bool {
		ni, _ := parseTicketSeq(tickets[i].ID)
		nj, _ := parseTicketSeq(tickets[j].ID)
		return ni < nj
	})
	// 工单编号容量：与 report 同一约束，可分配的最大序号为 math.MaxInt-1。
	if len(tickets) > math.MaxInt-s.data.NextTicketSeq {
		return nil, fmt.Errorf(
			"%w: 目标工单编号容量不足：下一序号 %d 无法容纳 %d 张导入工单，整批拒绝导入",
			errConflict, s.data.NextTicketSeq, len(tickets))
	}
	// 所选工单的任一请求标识已在目标绑定时整批拒绝，不改请求标识。
	srcReqByTicket := map[string]*requestBinding{}
	for i := range src.data.Requests {
		r := &src.data.Requests[i]
		srcReqByTicket[r.TicketID] = r
	}
	for _, t := range tickets {
		r := srcReqByTicket[t.ID]
		if r == nil {
			return nil, fmt.Errorf("数据内部错误：源工单 %s 缺少报修请求绑定", t.ID)
		}
		if s.findRequest(r.RequestID) != nil {
			return nil, fmt.Errorf(
				"%w: 所选工单的请求标识 %q 已在目标台账绑定，整批拒绝导入", errConflict, r.RequestID)
		}
	}
	// 所选资产的全部履历，按源履历序号升序，在目标最大序号之后依次分配。
	events := make([]Event, 0)
	for _, e := range src.data.Events {
		if selected[e.AssetID] {
			events = append(events, e)
		}
	}
	sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
	maxSeq := 0
	for _, e := range s.data.Events {
		if e.Seq > maxSeq {
			maxSeq = e.Seq
		}
	}
	// 履历序号容量：与 nextEventSeq 同一约束，可分配的最大序号为 math.MaxInt。
	if len(events) > math.MaxInt-maxSeq {
		return nil, fmt.Errorf(
			"%w: 目标履历序号容量不足：当前最大序号 %d 无法容纳 %d 条导入履历，整批拒绝导入",
			errConflict, maxSeq, len(events))
	}
	// 所选工单的全部备件领用记录，按源领用履历的全库序号整体排序（领用编号
	// 只定位记录，编号大小不代表领用先后），再按此顺序重新分配领用编号。
	srcTicketIDs := map[string]bool{}
	for _, t := range tickets {
		srcTicketIDs[t.ID] = true
	}
	srcWithdrawSeq := map[string]int{}
	for _, e := range src.data.Events {
		if e.Kind == eventPartWithdraw {
			srcWithdrawSeq[e.WithdrawalID] = e.Seq
		}
	}
	parts := make([]*PartWithdrawal, 0)
	for _, p := range src.data.Parts {
		if srcTicketIDs[p.TicketID] {
			parts = append(parts, p)
		}
	}
	sort.SliceStable(parts, func(i, j int) bool {
		return srcWithdrawSeq[parts[i].ID] < srcWithdrawSeq[parts[j].ID]
	})
	// 领用编号容量：与 withdrawPart 同一约束，可分配的最大序号为 math.MaxInt-1。
	if len(parts) > math.MaxInt-s.data.NextPartSeq {
		return nil, fmt.Errorf(
			"%w: 目标领用编号容量不足：下一序号 %d 无法容纳 %d 笔导入领用，整批拒绝导入",
			errConflict, s.data.NextPartSeq, len(parts))
	}
	// 所选工单的全部附件索引（有效与已撤销都复制），按源登记履历的全库序号
	// 整体排序（附件编号只定位记录，编号大小不代表登记先后），再按此顺序重新
	// 分配附件编号。只复制索引记录与履历，不复制资料文件；文件当前不可用不使
	// 导入失败。
	srcAttachRegSeq := map[string]int{}
	for _, e := range src.data.Events {
		if e.Kind == eventAttach {
			srcAttachRegSeq[e.AttachmentID] = e.Seq
		}
	}
	attachments := make([]*Attachment, 0)
	for _, a := range src.data.Attachments {
		if srcTicketIDs[a.TicketID] {
			attachments = append(attachments, a)
		}
	}
	sort.SliceStable(attachments, func(i, j int) bool {
		return srcAttachRegSeq[attachments[i].ID] < srcAttachRegSeq[attachments[j].ID]
	})
	// 附件编号容量：与 attach 同一约束，可分配的最大序号为 math.MaxInt-1。
	if len(attachments) > math.MaxInt-s.data.NextAttachSeq {
		return nil, fmt.Errorf(
			"%w: 目标附件编号容量不足：下一序号 %d 无法容纳 %d 条导入附件索引，整批拒绝导入",
			errConflict, s.data.NextAttachSeq, len(attachments))
	}

	// 检查全部通过，一次性应用合并。资产编号、名称、位置、状态与工单的描述、
	// 终态内容、负责人等业务信息原样保留；履历时间保留原瞬间与小数秒精度。
	for _, a := range assets {
		na := *a
		s.data.Assets = append(s.data.Assets, &na)
	}
	// 所选资产的保养计划原样复制（内容、首次到期日、间隔与下一到期日不变）；
	// 保养履历已随上方资产履历筛选一并复制，完成链自然接续。目标已有计划不变。
	planCount := 0
	for _, p := range src.data.Plans {
		if selected[p.AssetID] {
			np := *p
			s.data.Plans = append(s.data.Plans, &np)
			planCount++
		}
	}
	outcome := &importOutcome{assetIDs: ids, plans: planCount}
	remap := map[string]string{}
	next := s.data.NextTicketSeq
	for _, t := range tickets {
		nt := *t
		nt.ID = fmt.Sprintf("T%04d", next)
		remap[t.ID] = nt.ID
		s.data.Tickets = append(s.data.Tickets, &nt)
		r := srcReqByTicket[t.ID]
		s.data.Requests = append(s.data.Requests, requestBinding{
			RequestID:   r.RequestID,
			AssetID:     r.AssetID,
			Description: r.Description,
			TicketID:    nt.ID,
		})
		outcome.tickets = append(outcome.tickets, ticketRemap{OldID: t.ID, NewID: nt.ID})
		next++
	}
	s.data.NextTicketSeq = next
	// 备件领用记录按源领用顺序重新分配领用编号，工单引用同步替换；
	// 数量、累计退回与说明等业务信息原样保留。
	partIDs := map[string]string{}
	nextPart := s.data.NextPartSeq
	for _, p := range parts {
		np := *p
		np.ID = fmt.Sprintf("P%04d", nextPart)
		np.TicketID = remap[p.TicketID]
		partIDs[p.ID] = np.ID
		s.data.Parts = append(s.data.Parts, &np)
		outcome.parts = append(outcome.parts, partRemap{OldID: p.ID, NewID: np.ID})
		nextPart++
	}
	s.data.NextPartSeq = nextPart
	// 附件索引按源登记顺序重新分配附件编号，工单引用同步替换；
	// 路径、撤销状态、说明与撤销理由等业务信息原样保留。
	attachIDs := map[string]string{}
	nextAttach := s.data.NextAttachSeq
	for _, a := range attachments {
		na := *a
		na.ID = fmt.Sprintf("A%04d", nextAttach)
		na.TicketID = remap[a.TicketID]
		attachIDs[a.ID] = na.ID
		s.data.Attachments = append(s.data.Attachments, &na)
		outcome.attachments = append(outcome.attachments, attachRemap{OldID: a.ID, NewID: na.ID})
		nextAttach++
	}
	s.data.NextAttachSeq = nextAttach
	seq := maxSeq
	seqRemap := map[int]int{}
	for _, e := range events {
		seq++
		ne := e
		ne.Seq = seq
		ne.TicketID = remap[e.TicketID]
		ne.WithdrawalID = partIDs[e.WithdrawalID]
		ne.AttachmentID = attachIDs[e.AttachmentID]
		if e.Kind == eventPlanRevoke {
			// 撤销履历的目标完成序号随履历重编号同步替换：目标在源序号顺序中
			// 先于撤销出现（源台账已通过一致性检查），此处必然已有映射。
			ne.TargetSeq = seqRemap[e.TargetSeq]
		}
		seqRemap[e.Seq] = seq
		if e.Kind == eventPlanDone {
			outcome.completions = append(outcome.completions, completionRemap{OldSeq: e.Seq, NewSeq: seq})
		}
		s.data.Events = append(s.data.Events, ne)
	}
	return outcome, nil
}

