14	
15	// newStoreAt 在指定目录打开（或初始化）测试台账，使用确定性时钟。
16	func newStoreAt(t *testing.T, dir string) *store {
17		t.Helper()
18		s, err := openStore(dir)
19		if err != nil {
20			t.Fatalf("openStore(%s): %v", dir, err)
21		}
22		clock := time.Unix(1_700_000_000, 0)
23		s.now = func() time.Time {
24			clock = clock.Add(time.Second)
25			return clock
26		}
27		return s
28	}
29	
30	func mustSave(t *testing.T, s *store) {
31		t.Helper()
32		if err := s.save(); err != nil {
33			t.Fatalf("save: %v", err)
34		}
35	}
36	
37	func readFileBytes(t *testing.T, dir string) []byte {
38		t.Helper()
39		raw, err := os.ReadFile(filepath.Join(dir, dataFileName))
40		if err != nil {
41			t.Fatalf("读取数据文件: %v", err)
42		}
43		return raw
44	}
45	
46	// 编号重映射：工单按源序号升序从目标下一序号重排，履历在目标最大序号后续排，
47	// 请求绑定同步替换；重放、再次导入、编号延续与后续工单操作行为保持。
48	func TestImportRemapsTicketsAndEvents(t *testing.T) {
49		srcDir := filepath.Join(t.TempDir(), "src")
50		dstDir := filepath.Join(t.TempDir(), "dst")
51	
52		// 源台账：EQ-A 一关一开两张工单（含派工），EQ-B 一张未关闭，
53		// EQ-C 不导入，EQ-D 无工单。
54		src := newStoreAt(t, srcDir)
55		for _, a := range [][3]string{
56			{"EQ-A", "打印机", "一楼"}, {"EQ-B", "空调", "二楼"},
57			{"EQ-C", "投影仪", "三楼"}, {"EQ-D", "饮水机", "四楼"},
58		} {
59			if _, err := src.registerAsset(a[0], a[1], a[2]); err != nil {
60				t.Fatal(err)
61			}
62		}
63		if _, _, err := src.report("EQ-A", "卡纸", "req-a1"); err != nil { // T0001
64			t.Fatal(err)
65		}
66		if _, err := src.assignTicket("T0001", "张三", "首次派工"); err != nil {
67			t.Fatal(err)
68		}
69		if _, _, err := src.closeTicket("T0001", "已更换搓纸轮"); err != nil {
70			t.Fatal(err)
71		}
72		if _, _, err := src.report("EQ-A", "无法开机", "req-a2"); err != nil { // T0002
73			t.Fatal(err)
74		}
75		if _, _, err := src.report("EQ-B", "异响", "req-b1"); err != nil { // T0003
76			t.Fatal(err)
77		}
78		if _, _, err := src.report("EQ-C", "漏氟", "req-c1"); err != nil { // T0004，不导入
79			t.Fatal(err)
80		}
81		mustSave(t, src)
82	
83		// 目标台账：EQ-X 一张未关闭工单 T0001，下一序号 2，最大履历序号 1。
84		dst := newStoreAt(t, dstDir)
85		if _, err := dst.registerAsset("EQ-X", "叉车", "仓库"); err != nil {
86			t.Fatal(err)
87		}
88		if _, _, err := dst.report("EQ-X", "抖动", "req-x1"); err != nil {
89			t.Fatal(err)
90		}
91		mustSave(t, dst)
92	
93		srcBefore := readFileBytes(t, srcDir)
94		dstBefore := readFileBytes(t, dstDir)
95	
96		// 重复编号按一项处理。
97		outcome, err := importAssets(dstDir, srcDir, []string{"EQ-A", "EQ-B", "EQ-A", "EQ-D"})
98		if err != nil {
99			t.Fatalf("导入失败: %v", err)
100		}
101		if len(outcome.assetIDs) != 3 {
102			t.Fatalf("导入资产数 = %d, 想得到 3（重复编号按一项）", len(outcome.assetIDs))
103		}
104		wantMap := []ticketRemap{{"T0001", "T0002"}, {"T0002", "T0003"}, {"T0003", "T0004"}}
105		if len(outcome.tickets) != len(wantMap) {
106			t.Fatalf("映射工单数 = %d, 想得到 %d", len(outcome.tickets), len(wantMap))
107		}
108		for i, m := range outcome.tickets {
109			if m != wantMap[i] {
110				t.Fatalf("映射[%d] = %v, 想得到 %v", i, m, wantMap[i])
111			}
112		}
113	
114		// 源台账字节不变（只读）。
115		if got := readFileBytes(t, srcDir); string(got) != string(srcBefore) {
116			t.Fatal("导入不应修改源台账")
117		}
118		if string(dstBefore) == string(readFileBytes(t, dstDir)) {
119			t.Fatal("目标台账应已更新")
120		}
121	
122		// 重载后核对合并结果。
123		s, err := openStore(dstDir)
124		if err != nil {
125			t.Fatalf("重载目标: %v", err)
126		}
127		if s.data.NextTicketSeq != 5 {
128			t.Fatalf("下一工单序号 = %d, 想得到 5", s.data.NextTicketSeq)
129		}
130		if s.findAsset("EQ-C") != nil {
131			t.Fatal("未选择的 EQ-C 不应被导入")
132		}
133		a := s.findAsset("EQ-A")
134		if a == nil || a.Name != "打印机" || a.Location != "一楼" || a.Status != statusRepairing {
135			t.Fatalf("EQ-A 业务信息应原样保留，得到 %+v", a)
136		}
137		if d := s.findAsset("EQ-D"); d == nil || d.Status != statusAvailable {
138			t.Fatalf("无工单的 EQ-D 应导入为可用，得到 %+v", d)
139		}
140		// 目标原有记录不改编号、不改变业务含义。
141		orig := s.findTicket("T0001")
142		if orig == nil || orig.AssetID != "EQ-X" || orig.RequestID != "req-x1" || orig.Status != ticketOpen {
143			t.Fatalf("目标原有工单 T0001 不应改变，得到 %+v", orig)
144		}
145		// 映射后的工单保留业务信息。
146		t2 := s.findTicket("T0002")
147		if t2 == nil || t2.AssetID != "EQ-A" || t2.Description != "卡纸" || t2.RequestID != "req-a1" ||
148			t2.Status != ticketClosed || t2.Result != "已更换搓纸轮" || t2.Assignee != "张三" {
149			t.Fatalf("映射工单 T0002 业务信息应保留，得到 %+v", t2)
150		}
151		if t3 := s.findTicket("T0003"); t3 == nil || t3.Status != ticketOpen || t3.RequestID != "req-a2" {
152			t.Fatalf("映射工单 T0003 应保持未关闭，得到 %+v", t3)
153		}
154		if t4 := s.findTicket("T0004"); t4 == nil || t4.AssetID != "EQ-B" || t4.RequestID != "req-b1" {
155			t.Fatalf("映射工单 T0004 应属于 EQ-B，得到 %+v", t4)
156		}
157		// 请求绑定同步替换为新工单编号。
158		if r := s.findRequest("req-a1"); r == nil || r.TicketID != "T0002" {
159			t.Fatalf("req-a1 应绑定到 T0002，得到 %+v", r)
160		}
161		// 履历：在目标最大序号 1 之后按源顺序分配 2..6，工单引用已替换。
162		evA := s.eventsOf("EQ-A")
163		if len(evA) != 4 {
164			t.Fatalf("EQ-A 履历数 = %d, 想得到 4", len(evA))
165		}
166		wantKinds := []string{eventReport, eventAssign, eventClose, eventReport}
167		wantTickets := []string{"T0002", "T0002", "T0002", "T0003"}
168		for i, e := range evA {
169			if e.Seq != i+2 || e.Kind != wantKinds[i] || e.TicketID != wantTickets[i] {
170				t.Fatalf("履历[%d] = seq %d %s %s, 想得到 seq %d %s %s",
171					i, e.Seq, e.Kind, e.TicketID, i+2, wantKinds[i], wantTickets[i])
172			}
173		}
174		if evB := s.eventsOf("EQ-B"); len(evB) != 1 || evB[0].Seq != 6 || evB[0].TicketID != "T0004" {
175			t.Fatalf("EQ-B 履历应为 seq 6 的 T0004 报修，得到 %+v", evB)
176		}
177		// 履历时间保留原瞬间：与源台账逐条相等。
178		srcRe, err := openStore(srcDir)
179		if err != nil {
180			t.Fatal(err)
181		}
182		srcEv := append(srcRe.eventsOf("EQ-A"), srcRe.eventsOf("EQ-B")...)
183		dstEv := append(s.eventsOf("EQ-A"), s.eventsOf("EQ-B")...)
184		for i := range srcEv {
185			if !srcEv[i].Time.Equal(dstEv[i].Time) {
186				t.Fatalf("履历[%d] 时间 %s 应等于源时间 %s",
187					i, dstEv[i].Time, srcEv[i].Time)
188			}
189		}
190	
191		// 用原请求标识、资产与描述重放：返回映射后的工单及其当前状态，不创建记录。
192		before := len(s.data.Tickets)
193		tk, replay, err := s.report("EQ-A", "卡纸", "req-a1")
194		if err != nil || !replay || tk.ID != "T0002" || tk.Status != ticketClosed {
195			t.Fatalf("重放应返回已关闭的 T0002: %v replay=%v err=%v", tk, replay, err)
196		}
197		if len(s.data.Tickets) != before {
198			t.Fatal("重放不应创建记录")
199		}
200	
201		// 再次导入同一批资产按编号冲突拒绝，不作为报修请求重放。
202		if _, err := importAssets(dstDir, srcDir, []string{"EQ-A"}); !errors.Is(err, errConflict) {
203			t.Fatalf("再次导入应冲突，得到 %v", err)
204		}
205	
206		// 导入的未关闭工单可继续派工、关闭；编号从 5 延续。
207		s2, err := openStore(dstDir)
208		if err != nil {
209			t.Fatal(err)
210		}
211		if _, err := s2.assignTicket("T0004", "李四", "接手空调"); err != nil {
212			t.Fatalf("导入工单应可派工: %v", err)
213		}
214		if _, _, err := s2.closeTicket("T0003", "已更换电源"); err != nil {
215			t.Fatalf("导入工单应可关闭: %v", err)
216		}
217		if _, _, err := s2.closeTicket("T0004", "已更换风扇"); err != nil {
218			t.Fatal(err)
219		}
220		nk, replay, err := s2.report("EQ-B", "再次异响", "req-b2")
221		if err != nil || replay || nk.ID != "T0005" {
222			t.Fatalf("新工单应为 T0005: %v replay=%v err=%v", nk, replay, err)
223		}
224		mustSave(t, s2)
225		if _, err := openStore(dstDir); err != nil {
226			t.Fatalf("后续操作后的台账应保持一致: %v", err)
227		}
228	}
229	
230	// 旧库时间精度：源与目标原有履历的小数秒在导入与重新保存后都不损失；
231	// 序号间隔、数组乱序、时间不递增的旧台账均可导入；停机统计规则不变。
232	func TestImportPreservesLegacyTimePrecision(t *testing.T) {
233		srcDir := filepath.Join(t.TempDir(), "src")
234		dstDir := filepath.Join(t.TempDir(), "dst")
235		if err := os.MkdirAll(srcDir, 0o755); err != nil {
236			t.Fatal(err)
237		}
238		if err := os.MkdirAll(dstDir, 0o755); err != nil {
239			t.Fatal(err)
240		}
241	
242		// 源：序号有间隔、事件数组乱序、派工时间早于报修时间（时间不递增），
243		// 履历时间含小数秒。
244		srcLedger := `{
245	  "version": 1,
246	  "assets": [{"id":"EQ-1","name":"打印机","location":"一楼","status":"可用"}],
247	  "tickets": [{"id":"T0003","asset_id":"EQ-1","description":"卡纸","request_id":"req-1","status":"已关闭",
248	    "result":"已修复","created_at":"2026-10-01T08:00:00.123456789Z","closed_at":"2026-10-01T09:30:00.000000001Z",
249	    "assignee":"张三","assigned_at":"2026-10-01T07:00:00.25Z","assign_note":"上门"}],
