261		// 目标：原有履历带小数秒 .75，最大履历序号 4。
262		dstLedger := `{
263	  "version": 1,
264	  "assets": [{"id":"EQ-9","name":"空调","location":"二楼","status":"维修中"}],
265	  "tickets": [{"id":"T0001","asset_id":"EQ-9","description":"不制冷","request_id":"req-9","status":"未关闭","created_at":"2026-09-01T10:00:00Z"}],
