282		// 目标文件字节层面保留小数秒：导入的与目标原有的都不被截断。
283		raw := readFileBytes(t, dstDir)
284		for _, frag := range []string{"123456789", "000000001", "07:00:00.25", "10:00:00.75"} {
285			if !strings.Contains(string(raw), frag) {
286				t.Fatalf("保存后的目标文件应保留小数秒片段 %q", frag)
287			}
