289	
290		s, err := openStore(dstDir)
291		if err != nil {
292			t.Fatalf("重载: %v", err)
293		}
294		// 履历按源序号顺序（报修、派工、关闭）排在目标最大序号 4 之后，不按时间重排。
295		ev := s.eventsOf("EQ-1")
296		if len(ev) != 3 {
297			t.Fatalf("履历数 = %d, 想得到 3", len(ev))
298		}
299		want := []struct {
300			seq  int
301			kind string
302			ts   string
303		}{
304			{5, eventReport, "2026-10-01T08:00:00.123456789Z"},
305			{6, eventAssign, "2026-10-01T07:00:00.25Z"},
306			{7, eventClose, "2026-10-01T09:30:00.000000001Z"},
307		}
