345	// 冲突：资产编号在目标已存在、或所选工单的请求标识已在目标绑定时整批拒绝，
346	// 两边原文件字节保持不变。
347	func TestImportConflictRejectsBatch(t *testing.T) {
348		newSource := func(t *testing.T) string {
349			dir := filepath.Join(t.TempDir(), "src")
350			src := newStoreAt(t, dir)
351			if _, err := src.registerAsset("EQ-A", "打印机", "一楼"); err != nil {
352				t.Fatal(err)
353			}
354			if _, _, err := src.report("EQ-A", "卡纸", "req-a1"); err != nil {
355				t.Fatal(err)
356			}
357			mustSave(t, src)
358			return dir
359		}
360	
361		// 资产编号冲突。
362		srcDir := newSource(t)
363		dstDir := filepath.Join(t.TempDir(), "dst")
364		dst := newStoreAt(t, dstDir)
365		if _, err := dst.registerAsset("EQ-A", "另一台打印机", "二楼"); err != nil {
366			t.Fatal(err)
367		}
368		mustSave(t, dst)
369		srcBefore, dstBefore := readFileBytes(t, srcDir), readFileBytes(t, dstDir)
370		if _, err := importAssets(dstDir, srcDir, []string{"EQ-A"}); !errors.Is(err, errConflict) {
371			t.Fatalf("资产编号冲突应拒绝，得到 %v", err)
372		}
373		if string(readFileBytes(t, srcDir)) != string(srcBefore) ||
374			string(readFileBytes(t, dstDir)) != string(dstBefore) {
375			t.Fatal("冲突拒绝不应改动任何文件")
376		}
377	
378		// 请求标识冲突：目标已有不同资产绑定了 req-a1。
379		srcDir2 := newSource(t)
380		dstDir2 := filepath.Join(t.TempDir(), "dst")
381		dst2 := newStoreAt(t, dstDir2)
382		if _, err := dst2.registerAsset("EQ-Z", "叉车", "仓库"); err != nil {
383			t.Fatal(err)
384		}
385		if _, _, err := dst2.report("EQ-Z", "抖动", "req-a1"); err != nil {
386			t.Fatal(err)
387		}
388		mustSave(t, dst2)
389		srcBefore2, dstBefore2 := readFileBytes(t, srcDir2), readFileBytes(t, dstDir2)
390		if _, err := importAssets(dstDir2, srcDir2, []string{"EQ-A"}); !errors.Is(err, errConflict) {
391			t.Fatalf("请求标识冲突应拒绝，得到 %v", err)
392		}
393		if string(readFileBytes(t, srcDir2)) != string(srcBefore2) ||
394			string(readFileBytes(t, dstDir2)) != string(dstBefore2) {
395			t.Fatal("请求标识冲突拒绝不应改动任何文件")
396		}
397		s, err := openStore(dstDir2)
398		if err != nil {
399			t.Fatal(err)
400		}
401		if s.findAsset("EQ-A") != nil || len(s.data.Tickets) != 1 {
402			t.Fatal("整批拒绝不应留下部分资产或工单")
403		}
404	}
