418		writeDst := func(t *testing.T, nextTicketSeq, maxEventSeq int) (string, []byte) {
419			t.Helper()
420			dir := t.TempDir()
421			ledger := fmt.Sprintf(`{
422	  "version": 1,
423	  "assets": [{"id":"EQ-T","name":"空调","location":"二楼","status":"维修中"}],
424	  "tickets": [{"id":"T0001","asset_id":"EQ-T","description":"不制冷","request_id":"req-t1","status":"未关闭","created_at":"2026-09-01T10:00:00Z"}],
425	  "events": [{"seq":%[2]d,"asset_id":"EQ-T","ticket_id":"T0001","kind":"报修","content":"不制冷","time":"2026-09-01T10:00:00Z"}],
426	  "requests": [{"request_id":"req-t1","asset_id":"EQ-T","description":"不制冷","ticket_id":"T0001"}],
427	  "next_ticket_seq": %[1]d
428	}`, nextTicketSeq, maxEventSeq)
