440			t.Fatalf("工单编号容量不足应冲突拒绝，得到 %v", err)
441		}
442		if string(readFileBytes(t, dstDir)) != string(dstBefore) ||
443			string(readFileBytes(t, srcDir)) != string(srcBefore) {
444			t.Fatal("容量不足拒绝不应改动任何文件")
445		}
446	
447		// 履历序号容量不足：目标最大履历序号已为 math.MaxInt。
