457	// 写入失败：目标目录不可写时整批失败，两边原文件字节不变，
458	// 重载后无部分资产、履历或请求绑定，目标编号未被消耗。
459	func TestImportWriteFailureLeavesFilesUntouched(t *testing.T) {
460		srcDir := filepath.Join(t.TempDir(), "src")
461		src := newStoreAt(t, srcDir)
462		if _, err := src.registerAsset("EQ-S", "打印机", "一楼"); err != nil {
463			t.Fatal(err)
464		}
465		if _, _, err := src.report("EQ-S", "卡纸", "req-s1"); err != nil {
466			t.Fatal(err)
