func decodeStoreData(raw []byte) (*storeData, error) {
    if len(bytes.TrimSpace(raw)) == 0 {
        return nil, errors.New("已损坏：文件为空")
    }
    var d storeData
    if err := json.Unmarshal(raw, &d); err != nil {
        return nil, fmt.Errorf("已损坏：%w", err)
    }
    if d.EventsJSON != nil {
        d.Events = make([]Event, len(d.EventsJSON))
        for i, ej := range d.EventsJSON {
            ev, err := ej.toEvent()
            if err != nil {
                return nil, fmt.Errorf("已损坏：%w", err)
            }
            d.Events[i] = ev
        }
    }
    if d.Plans == nil { d.Plans = []*Plan{} }
    if d.Parts == nil { d.Parts = []*PartWithdrawal{} }
    if d.NextPartSeq == 0 && len(d.Parts) == 0 { d.NextPartSeq = 1 }
    if d.Attachments == nil { d.Attachments = []*Attachment{} }
    if d.NextAttachSeq == 0 && len(d.Attachments) == 0 { d.NextAttachSeq = 1 }
    if err := validateData(&d); err != nil {
        return nil, fmt.Errorf("内容相互矛盾：%w", err)
    }
    return &d, nil
}
