// 相互矛盾都返回指明问题类别的错误，调用方必须拒绝查询与写入。不做任何修复：
// 不补字段、不重编号、不删除记录。无保养、备件或附件字段的有效旧库直接使用。
func decodeStoreData(raw []byte) (*storeData, error) {
	if len(bytes.TrimSpace(raw)) == 0 {
		return nil, errors.New("已损坏：文件为空")
	}
