	if err := json.Unmarshal(raw, &d); err != nil {
		return nil, fmt.Errorf("已损坏：%w", err)
	}
	if d.EventsJSON != nil {
		d.Events = make([]Event, len(d.EventsJSON))
		for i, ej := range d.EventsJSON {
			ev, err := ej.toEvent()
			if err != nil {
				return nil, fmt.Errorf("已损坏：%w", err)
			}
			d.Events[i] = ev
		}
	}
	// 无保养字段的有效旧库直接使用：缺省视为没有任何保养计划。
	if d.Plans == nil {
		d.Plans = []*Plan{}
	}
	// 无备件字段的有效旧库直接使用：缺省视为没有任何备件领用记录，
	// 领用编号计数器从 1 开始。
	if d.Parts == nil {
		d.Parts = []*PartWithdrawal{}
	}
	if d.NextPartSeq == 0 && len(d.Parts) == 0 {
		d.NextPartSeq = 1
	}
	// 无附件字段的有效旧库直接使用：缺省视为没有任何附件索引记录，
	// 附件编号计数器从 1 开始。
	if d.Attachments == nil {
		d.Attachments = []*Attachment{}
	}
	if d.NextAttachSeq == 0 && len(d.Attachments) == 0 {
		d.NextAttachSeq = 1
	}
	if err := validateData(&d); err != nil {
		return nil, fmt.Errorf("内容相互矛盾：%w", err)
	}
	return &d, nil
}

// encodeStoreData 把业务数据编码为台账字节（缩进 JSON）：先由内存履历生成
// 持久化的 EventsJSON，时间以 RFC3339Nano 保留小数秒精度。调用方负责校验
// 与落盘。
func encodeStoreData(d *storeData) ([]byte, error) {
	d.EventsJSON = make([]eventJSON, len(d.Events))
	for i, e := range d.Events {
		d.EventsJSON[i] = e.toJSON()
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	if err := enc.Encode(d); err != nil {
		return nil, fmt.Errorf("编码数据失败: %w", err)
	}
	return buf.Bytes(), nil
}

